import{_ as a,c as s,o as n,ag as o}from"./chunks/framework.CazwtNDk.js";const u=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"quickstart.md","filePath":"quickstart.md","lastUpdated":1788803607000}'),t={name:"quickstart.md"};function r(l,e,i,c,p,d){return n(),s("div",null,e[0]||(e[0]=[o(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Calendar runs as a Go service with an embedded browser UI. <strong>PostgreSQL is required</strong>, including when running a prebuilt binary. Node.js and pnpm are needed only when building or developing the UI from source.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><h3 id="binary" tabindex="-1">Binary <a class="header-anchor" href="#binary" aria-label="Permalink to &quot;Binary&quot;">​</a></h3><ol><li>Download the archive for your operating system and architecture from the <a href="https://github.com/rakunlabs/calendar/releases/latest" target="_blank" rel="noreferrer">latest release</a>.</li><li>Extract the binary and provision a PostgreSQL database and schema.</li><li>Create a configuration file using the example below, setting both database connection strings.</li><li>Start the extracted binary with the configuration path:</li></ol><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme vp-code" tabindex="0"><code><span class="line"><span style="color:#EEFFFF;">CONFIG_FILE</span><span style="color:#89DDFF;">=</span><span style="color:#C3E88D;">/path/to/calendar.yaml</span><span style="color:#FFCB6B;"> ./calendar</span></span></code></pre></div><p>Open <code>http://localhost:8080/calendar/</code>. The service applies pending database migrations before starting the HTTP server; the migration connection needs permission to create and alter the application&#39;s tables.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Set <code>CONFIG_FILE</code> to the configuration path, or use <code>calendar.[toml|yaml|yml|json]</code> in the current working directory. The following example matches the local development database:</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki material-theme vp-code" tabindex="0"><code><span class="line"><span style="color:#F07178;">log_level</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> info</span></span>
<span class="line"><span style="color:#F07178;">port</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 8080</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F07178;">db_type</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> pgx</span></span>
<span class="line"><span style="color:#F07178;">db_datasource</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> postgres://postgres@localhost:5432/postgres?sslmode=disable</span></span>
<span class="line"><span style="color:#F07178;">db_schema</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> public</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F07178;">migrate</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#F07178;">  db_datasource</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> postgres://postgres@localhost:5432/postgres?sslmode=disable</span></span>
<span class="line"><span style="color:#F07178;">  db_type</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> pgx</span></span>
<span class="line"><span style="color:#F07178;">  db_schema</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> public</span></span>
<span class="line"><span style="color:#F07178;">  db_table</span><span style="color:#89DDFF;">:</span><span style="color:#C3E88D;"> calendar_migrations</span></span></code></pre></div><p>The application and migration connections are configured separately; neither datasource has a default. They can use different database credentials, but must point to the same application database and schema. Use password authentication and an appropriate TLS configuration for your PostgreSQL deployment rather than copying the local connection strings into production.</p><h2 id="run-from-source" tabindex="-1">Run From Source <a class="header-anchor" href="#run-from-source" aria-label="Permalink to &quot;Run From Source&quot;">​</a></h2><p>From the repository root, with Go matching <code>go.mod</code>, Docker with Compose, Node.js 22, and the pnpm version pinned in <code>_ui/package.json</code> installed:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">make</span><span style="color:#C3E88D;"> env</span></span>
<span class="line"><span style="color:#FFCB6B;">make</span><span style="color:#C3E88D;"> run</span></span></code></pre></div><p><code>make env</code> starts PostgreSQL on port 5432 using <code>env/docker-compose.yaml</code>. The checked-in <code>calendar.yaml</code> configures both connections for that database. <code>make run</code> installs UI dependencies with the frozen lockfile, builds the embedded UI, and runs <code>go run cmd/calendar/main.go</code>. Startup also runs migrations. Wait for the database to be ready before starting the service.</p><p>Open <code>http://localhost:8080/calendar/</code>. For frontend development, run <code>make ui-dev</code> in a second terminal and open <code>http://localhost:5173/calendar/</code>; Vite proxies API requests to the Go service on port 8080. See the <a href="https://github.com/rakunlabs/calendar/blob/main/_ui/README.md" target="_blank" rel="noreferrer">UI README</a> for build and test commands.</p><div class="warning custom-block"><p class="custom-block-title">Development Database</p><p>The Compose database uses <code>POSTGRES_HOST_AUTH_METHOD=trust</code> and publishes port 5432. It is for local development only; do not expose it to untrusted networks. <code>make env-down</code> runs <code>docker compose down --volumes</code> and removes the local database volumes and their data. It is not a data-preserving stop command.</p></div><h2 id="before-sharing" tabindex="-1">Before Sharing <a class="header-anchor" href="#before-sharing" aria-label="Permalink to &quot;Before Sharing&quot;">​</a></h2><p>Calendar adds no authentication to the UI or API. Protect both with deployment-level access controls. <code>Updated by</code> sends an optional <code>X-User</code> audit label, not a login or verified identity. Entity filters and subscription URLs do not enforce authorization.</p><p>Continue with the <a href="/calendar/ui-guide">User Guide</a> to create events, assign calendars, and choose the scope of ICS downloads and subscriptions.</p>`,20)]))}const m=a(t,[["render",r]]);export{u as __pageData,m as default};
